import math


def chunk_text(text, size=20, overlap=5):
    paragraphs = [p.strip() for p in str(text or '').splitlines() if p.strip()]
    chunks = []
    current = ''
    for paragraph in paragraphs:
        while len(paragraph) > size:
            piece, paragraph = paragraph[:size], paragraph[size:]
            if current:
                chunks.append(current)
                current = ''
            chunks.append(piece)
        candidate = (current + ' ' + paragraph).strip() if current else paragraph
        if len(candidate) <= size:
            current = candidate
        else:
            chunks.append(current)
            current = paragraph
    if current:
        chunks.append(current)
    if overlap <= 0 or len(chunks) < 2:
        return chunks
    overlapped = [chunks[0]]
    for index in range(1, len(chunks)):
        tail = chunks[index - 1][-overlap:]
        overlapped.append((tail + chunks[index])[:size])
    return overlapped


def cosine(a, b):
    a = list(a or [])
    b = list(b or [])
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return dot / (norm_a * norm_b)


def search(query_vec, docs, top_k=2):
    scored = [(doc_id, round(cosine(query_vec, vector), 4)) for doc_id, vector in docs or []]
    scored.sort(key=lambda item: (-item[1], str(item[0])))
    return scored[:top_k]


print(chunk_text('列表是有序容器\n元组不可变\n字典是键值对\n集合去重', size=12, overlap=3))
print(cosine([1, 0], [1, 0]), cosine([1, 0], [0, 1]), cosine([], [1]))
docs = [('d1', [1, 0]), ('d2', [0.9, 0.1]), ('d3', [0, 1])]
print(search([1, 0], docs, top_k=2))
